import static org.junit.Assert.*;

public class MutableDateTime_addYears_TriageGen2Test {







    @Test
    public void testAddYears_LeapYearToNonLeapYear() {
        // Feb 29th in a leap year
        MutableDateTime dt = new MutableDateTime(2024, 2, 29, 0, 0, 0, 0);
        // Adding 1 year should result in Feb 28th in 2025
        dt.addYears(1);
        assertEquals(2025, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }






}

